# Dapr pub/sub component: app publishes via Dapr API, infrastructure swappable
apiVersion: dapr.io/v1alpha1
kind: Component
metadata: { name: payments-pubsub, namespace: payments }
spec:
  type: pubsub.kafka
  version: v1
  metadata:
  - { name: brokers, value: "kafka.platform:9092" }
  - { name: authType, value: "mtls" }
---
# Dapr configuration: rely on the mesh for mTLS to avoid double encryption
apiVersion: dapr.io/v1alpha1
kind: Configuration
metadata: { name: dapr-config, namespace: payments }
spec:
  mtls: { enabled: false }
  tracing: { samplingRate: "0.05", otel: { endpointAddress: "otel-collector.observability:4317", protocol: grpc } }
