// Without a mesh: consistent resilience and service auth in a shared .NET defaults package
builder.Services.AddHttpClient<LedgerClient>(c => c.BaseAddress = new Uri("https://ledger.internal"))
    .AddStandardResilienceHandler(o =>
    {
        o.AttemptTimeout.Timeout = TimeSpan.FromSeconds(1);
        o.TotalRequestTimeout.Timeout = TimeSpan.FromSeconds(3);
        o.Retry.MaxRetryAttempts = 2;
        o.CircuitBreaker.FailureRatio = 0.2;
    })
    .AddClientCredentialsTokenHandler("ledger");            // OAuth client credentials, audience api://ledger

builder.Services.AddOpenTelemetry().WithTracing(t => t.AddAspNetCoreInstrumentation().AddHttpClientInstrumentation().AddOtlpExporter());
// Encryption: Kestrel HTTPS with cert-manager issued certificates; segmentation: NetworkPolicies per namespace
