public sealed record MeshCost(int Pods, int Nodes, double SidecarVcpu, double SidecarGb, double ZtunnelVcpuPerNode,
                              int Waypoints, double WaypointVcpu, double VcpuMonthly, double GbMonthly, double TelemetryMonthly)
{
    public double Sidecar => Pods * (SidecarVcpu * VcpuMonthly + SidecarGb * GbMonthly) + TelemetryMonthly;
    public double Ambient => Nodes * ZtunnelVcpuPerNode * VcpuMonthly + Waypoints * WaypointVcpu * VcpuMonthly + TelemetryMonthly * 0.6;
}

var m = new MeshCost(Pods: 3000, Nodes: 150, SidecarVcpu: 0.1, SidecarGb: 0.128, ZtunnelVcpuPerNode: 0.2,
                     Waypoints: 20, WaypointVcpu: 1.0, VcpuMonthly: 25, GbMonthly: 3, TelemetryMonthly: 9000);
Console.WriteLine($"sidecar {m.Sidecar:N0}/month vs ambient {m.Ambient:N0}/month");
