// Capability replacement before removing the mesh: TLS + service tokens + resilience + telemetry in one defaults package
public static class ServiceDefaults
{
    public static IHostApplicationBuilder AddBankServiceDefaults(this IHostApplicationBuilder b)
    {
        b.WebHost.ConfigureKestrel(k => k.ConfigureHttpsDefaults(h =>
        {
            h.ServerCertificate = CertificateLoader.FromMountedSecret("/certs/tls.crt", "/certs/tls.key");   // cert-manager issued
            h.ClientCertificateMode = ClientCertificateMode.RequireCertificate;                              // mutual TLS
        }));
        b.Services.ConfigureHttpClientDefaults(h => h
            .AddStandardResilienceHandler()
            .ConfigurePrimaryHttpMessageHandler(() => MtlsHandler.FromMountedSecret("/certs")));
        b.Services.AddOpenTelemetry().WithTracing(t => t.AddAspNetCoreInstrumentation().AddHttpClientInstrumentation().AddOtlpExporter());
        return b;
    }
}
