# Portable mesh routing with Gateway API (GAMMA): HTTPRoute attached to a Service, not a vendor CRD
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata: { name: ledger-canary, namespace: ledger }
spec:
  parentRefs:
  - { group: "", kind: Service, name: ledger-api, port: 8080 }
  rules:
  - matches: [{ path: { type: PathPrefix, value: /journal-entries } }]
    backendRefs:
    - { name: ledger-api-v1, port: 8080, weight: 90 }
    - { name: ledger-api-v2, port: 8080, weight: 10 }
    timeouts: { request: 3s }
